      else if (msg.includes('password')) { setErrors({ password: msg }); }
    } finally {
      setLoading(false);
    }
  };

  const stepContent = [
    /* ── Step 0: Account Info ── */
    <motion.div key="s0" initial={{ opacity: 0, x: 30 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -30 }}
