export default function LoginPage() {
  const navigate = useNavigate();
  const { setUser } = useAuthStore();
  const [form, setForm] = useState({ phone_number: '', password: '' });
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [activeContact, setActiveContact] = useState(0);
  const [phoneError, setPhoneError] = useState('');
  const [passwordError, setPasswordError] = useState('');

  useEffect(() => {
    const t = setInterval(() => setActiveContact(c => (c + 1) % CONTACTS.length), 3500);
    return () => clearInterval(t);
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setPhoneError('');
    setPasswordError('');

    let hasErr = false;
    if (!form.phone_number.trim()) { setPhoneError('Phone number is required'); hasErr = true; }
    if (!form.password) { setPasswordError('Password is required'); hasErr = true; }
    if (hasErr) return;

    setLoading(true);
    try {
      const { data } = await api.post('/auth/login', {
        phone_number: form.phone_number.replace(/\s/g, ''),
        password: form.password,
      });
      localStorage.setItem('access_token', data.access_token);
      localStorage.setItem('refresh_token', data.refresh_token);
      setUser(data.user);
      toast.success(`Welcome back, ${data.user.full_name}! 👋`);
      // Register push notifications after login
      registerPushNotifications(data.access_token).catch(() => {});
      navigate('/');
    } catch (err) {
      const msg = err.response?.data?.error || 'Login failed';
      if (msg.toLowerCase().includes('phone') || msg.toLowerCase().includes('credentials')) {
        setPhoneError('Incorrect phone number or password');
        setPasswordError(' ');
      } else if (msg.toLowerCase().includes('suspend') || msg.toLowerCase().includes('ban')) {
        toast.error(msg);
      } else {
        toast.error(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex h-screen overflow-hidden font-sans">
      {/* ── LEFT: Animated Bitese preview ── */}
      <div className="hidden lg:flex flex-col flex-1 bg-[#075E54] relative overflow-hidden select-none">
