          {/* Logo */}
          <div className="flex items-center gap-3 mb-8">
            <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-[#075E54] to-[#25D366] flex items-center justify-center shadow-lg shadow-green-200">
              <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24">
                <path d="M12 2C6.48 2 2 6.48 2 12c0 1.54.36 3 .97 4.29L2 22l5.71-.97C9 21.64 10.46 22 12 22c5.52 0 10-4.48 10-10S17.52 2 12 2z"/>
              </svg>
            </div>
            <div>
              <h1 className="text-xl font-bold text-gray-900">Bitese</h1>
              <p className="text-gray-400 text-xs">Your world, connected</p>
            </div>
          </div>

          <motion.div initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }}>
            <h2 className="text-2xl font-bold text-gray-900 mb-1">Welcome back</h2>
            <p className="text-gray-400 mb-6 text-sm">Sign in to continue your conversations</p>

            <form onSubmit={handleSubmit} className="space-y-4" noValidate>
              {/* Phone */}
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1.5">Phone Number</label>
                <div className="relative">
                  <FiPhone className="absolute left-4 top-1/2 -translate-y-1/2 text-[#25D366]" size={16} />
                  <input
                    type="tel"
                    value={form.phone_number}
                    onChange={e => { setForm(p => ({ ...p, phone_number: e.target.value })); setPhoneError(''); }}
                    placeholder="+256 701 234 567"
                    autoComplete="tel"
                    className={`w-full pl-11 pr-4 py-3 border-2 rounded-2xl focus:outline-none focus:ring-4 transition text-sm
                      ${phoneError ? 'border-red-300 focus:border-red-400 focus:ring-red-50' : 'border-gray-200 focus:border-[#25D366] focus:ring-green-50'}`}
                  />
                </div>
                <AnimatePresence>
                  {phoneError && (
                    <motion.p initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}
                      className="text-xs text-red-500 mt-1 pl-1">{phoneError}</motion.p>
                  )}
                </AnimatePresence>
              </div>

