            Status.expires_at > datetime.utcnow()
        ).order_by(Status.created_at.desc()).all()
        return jsonify({'statuses': [s.to_dict() for s in statuses]}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500
