import AsyncStorage from '@react-native-async-storage/async-storage';

export const Storage = {
  get: (key) => AsyncStorage.getItem(key),
  set: (key, value) => AsyncStorage.setItem(key, value),
  remove: (key) => AsyncStorage.removeItem(key),
  clear: () => AsyncStorage.clear(),

  getJSON: async (key) => {
    const val = await AsyncStorage.getItem(key);
    try { return val ? JSON.parse(val) : null; } catch { return null; }
  },
  setJSON: (key, value) => AsyncStorage.setItem(key, JSON.stringify(value)),
};

export const TokenStorage = {
  getAccessToken: () => Storage.get('access_token'),
  getRefreshToken: () => Storage.get('refresh_token'),
  setTokens: (access, refresh) => Promise.all([
    Storage.set('access_token', access),
    Storage.set('refresh_token', refresh),
  ]),
  clearTokens: () => Promise.all([
    Storage.remove('access_token'),
    Storage.remove('refresh_token'),
  ]),
};

import axios from 'axios';
import { API_URL } from '../config';
import { TokenStorage } from './storage';

const api = axios.create({
  baseURL: API_URL,
  timeout: 15000,
  headers: { 'Content-Type': 'application/json' },
});

api.interceptors.request.use(async (config) => {
  const token = await TokenStorage.getAccessToken();
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

let isRefreshing = false;
let failedQueue = [];

const processQueue = (error, token = null) => {
  failedQueue.forEach(prom => error ? prom.reject(error) : prom.resolve(token));
  failedQueue = [];
};

api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;
    if (error.response?.status === 401 && !originalRequest._retry) {
      if (isRefreshing) {
        return new Promise((resolve, reject) => {
          failedQueue.push({ resolve, reject });
        }).then(token => {
          originalRequest.headers.Authorization = `Bearer ${token}`;
          return api(originalRequest);
        });
      }
      originalRequest._retry = true;
      isRefreshing = true;
      try {
        const refreshToken = await TokenStorage.getRefreshToken();
        if (!refreshToken) throw new Error('No refresh token');
        const { data } = await axios.post(`${API_URL}/auth/refresh`, {}, {
          headers: { Authorization: `Bearer ${refreshToken}` },
        });
        const newToken = data.access_token;
        await TokenStorage.setTokens(newToken, refreshToken);
        processQueue(null, newToken);
        originalRequest.headers.Authorization = `Bearer ${newToken}`;
        return api(originalRequest);
      } catch (err) {
        processQueue(err);
        await TokenStorage.clearTokens();
        return Promise.reject(err);
      } finally {
        isRefreshing = false;
      }
    }
    return Promise.reject(error);
  }
);

export default api;

